INSERT INTO `email_logs` (`id`, `user_id`, `booking_id`, `recipient_email`, `subject`, `body_html`, `status`, `error_message`, `created_at`) VALUES
(1, 9, NULL, 'hirananjana12@gmail.com', '🎟️ Booking Confirmation & E-Ticket - Mariens Live in concert [Code: EVT-159-6495]', '\n    <!DOCTYPE html>\n    <html>\n    <head>\n      <meta charset=\"utf-8\">\n      <style>\n        body { font-family: \'Segoe UI\', Arial, sans-serif; background-color: #f4f6f9; margin: 0; padding: 20px; color: #333; }\n        .ticket-card { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 10px 25px rgba(0,0,0,0.1); border: 1px solid #e2e8f0; }\n        .header { background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%); color: #ffffff; padding: 24px; text-align: center; }\n        .header h1 { margin: 0; font-size: 24px; font-weight: 700; }\n        .header p { margin: 6px 0 0 0; opacity: 0.9; font-size: 14px; }\n        .content { padding: 24px; }\n        .detail-row { display: flex; justify-content: space-between; margin-bottom: 12px; border-bottom: 1px dashed #e2e8f0; padding-bottom: 8px; }\n        .detail-label { color: #64748b; font-size: 14px; font-weight: 600; }\n        .detail-val { color: #0f172a; font-size: 14px; font-weight: 700; }\n        .qr-section { text-align: center; margin: 24px 0; background: #f8fafc; padding: 20px; border-radius: 8px; border: 1px solid #e2e8f0; }\n        .qr-code-box { display: inline-block; padding: 10px; background: #fff; border-radius: 8px; border: 1px solid #cbd5e1; }\n        .footer { background: #f1f5f9; padding: 16px; text-align: center; font-size: 12px; color: #64748b; }\n      </style>\n    </head>\n    <body>\n      <div class=\"ticket-card\">\n        <div class=\"header\">\n          <h1>🎉 Ticket Confirmation</h1>\n          <p>EventEase Ticket Reservation Platform</p>\n        </div>\n        <div class=\"content\">\n          <p>Dear <strong>Hiran Anajana</strong>,</p>\n          <p>Thank you for your reservation! Your payment has been confirmed. Below are your event ticket details:</p>\n          \n          <div style=\"margin: 20px 0;\">\n            <div class=\"detail-row\">\n              <span class=\"detail-label\">Event Name:</span>\n              <span class=\"detail-val\">Mariens Live in concert</span>\n            </div>\n            <div class=\"detail-row\">\n              <span class=\"detail-label\">Ticket Code:</span>\n              <span class=\"detail-val\" style=\"color:#4f46e5;\">EVT-159-6495</span>\n            </div>\n            <div class=\"detail-row\">\n              <span class=\"detail-label\">Date & Location:</span>\n              <span class=\"detail-val\">2026-07-25 | Negombo</span>\n            </div>\n            <div class=\"detail-row\">\n              <span class=\"detail-label\">Quantity:</span>\n              <span class=\"detail-val\">1 Ticket(s)</span>\n            </div>\n            <div class=\"detail-row\">\n              <span class=\"detail-label\">Total Amount Paid:</span>\n              <span class=\"detail-val\" style=\"color:#16a34a;\">LKR 7,500.00</span>\n            </div>\n          </div>\n\n          <div class=\"qr-section\">\n            <h3 style=\"margin-top:0; color:#1e293b;\">Your Entry QR Code</h3>\n            <p style=\"font-size:12px; color:#64748b; margin-bottom:12px;\">Present this code at the venue gate for instant scanning and validation.</p>\n            <div class=\"qr-code-box\">\n              <img src=\"http://localhost/EventEase/backend/uploads/qr/ticket_159.png\" alt=\"QR Code\" width=\"180\" height=\"180\" style=\"display:block;\" />\n            </div>\n            <p style=\"font-size:13px; font-weight:bold; color:#4f46e5; margin-top:10px;\">EVT-159-6495</p>\n          </div>\n          \n          <p style=\"font-size:13px; color:#64748b;\">You can also access, download, or print your digital PDF ticket anytime from your EventEase Customer Dashboard under \"My Bookings\".</p>\n        </div>\n        <div class=\"footer\">\n          EventEase Digital Ticketing • Automated Confirmation • Support: sup